23	async fn test_lookup_throttled_mock(head_object_throttled: bool, list_object_throttled: bool) {
24	    let bucket = "bucket";
25	    let key = "throttled";
26	    let list_503_response = r#"
27	    <?xml version=\"1.0\" encoding=\"UTF-8\"?>
28	    <Error>
29	        <Code>SlowDown</Code>
30	        <RequestId>765b43b1b388405cb10ac1c510e7b6cd</RequestId>
31	        <HostId>00000000000000000000000000000000000/000000000000000000==</HostId>
32	    </Error>
33	    "#
34	    .to_string();
35	    let head_object_503_headers = [];
36	    let head_object_ok_headers = [
37	        ("ETag", "71a5b8dcb22444f1b2b899dedc1e4122"),
38	        ("Date", "Thu, 12 Jan 2023 00:04:21 GMT"),
39	        ("Last-Modified", "Tue, 10 Jan 2023 23:39:32 GMT"),
40	        ("Accept-Ranges", "bytes"),
41	        ("Content-Range", "bytes 0-65535/65536"),
42	        ("Content-Type", "binary/octet-stream"),
43	        ("Content-Length", "1024"),
44	    ];
45	
46	    let (fs, server) = create_fs_with_mock_s3(bucket);
47	
48	    // lookup will issue 2 S3 calls, let's mock them
49	    // those are the *assumed* S3 responses, based on: https://docs.aws.amazon.com/AmazonS3/latest/API/ErrorResponses.html
50	    let (list_http_code, list_response) = if list_object_throttled {
51	        (503, list_503_response)
52	    } else {
53	        (200, list_empty_response(bucket, key))
54	    };
55	    let (head_object_http_code, head_object_headers): (u16, &[(&str, &str)]) = if head_object_throttled {
56	        (503, &head_object_503_headers)
57	    } else {
58	        (200, &head_object_ok_headers)
59	    };
60	    server.mock(|when, then| {
61	        when.method(Method::GET)
62	            .path(format!("/{bucket}/"))
63	            .query_param("list-type", "2")
64	            .query_param("prefix", format!("{key}/"));
65	        then.status(list_http_code).body(list_response);
66	    });
67	    server.mock(|when, then| {
68	        when.method(Method::HEAD).path(format!("/{bucket}/{key}"));
69	        set_response_headers(then.status(head_object_http_code), head_object_headers);
70	    });
71	
72	    // perform a lookup
73	    let err = fs
74	        .lookup(FUSE_ROOT_INODE, key.as_ref())
75	        .await
76	        .expect_err("lookup must fail");
77	    let actual_errno = nix::errno::Errno::from_raw(err.to_errno());
78	    let expected_errno = nix::errno::Errno::EIO;
79	    assert_eq!(
80	        actual_errno, expected_errno,
81	        "lookup failure due to HTTP 503 must return {expected_errno:?}",
82	    );
83	    let metadata = err.meta();
84	    assert_eq!(
85	        *metadata,
86	        ErrorMetadata {
87	            client_error_meta: ClientErrorMetadata {
88	                http_code: Some(503),
89	                error_code: Some("SlowDown".to_string()),
90	                error_message: Some("Please reduce your request rate.".to_string()),
91	            },
92	            error_code: Some(MOUNTPOINT_ERROR_CLIENT.to_string()),
93	            s3_bucket_name: Some(bucket.to_string()),
94	            s3_object_key: Some(key.to_string())
95	        }
96	    );
97	}
